-- Skill configuration restoration. Original ov_skilldesc rows, all original
-- rank 1..5 numbers, character points and player saves remain untouched.
-- Run after migration 61. All content is typed; no formulas/scripts are stored.
CREATE TABLE IF NOT EXISTS game_skill_configuration_manifest (
 id integer PRIMARY KEY CHECK(id=1), expected_skills integer NOT NULL CHECK(expected_skills>0),
 expected_synergies integer NOT NULL CHECK(expected_synergies>0),
 expected_prerequisite_overrides integer NOT NULL CHECK(expected_prerequisite_overrides>=0),
 expected_restored_statuses integer NOT NULL CHECK(expected_restored_statuses>0),
 expected_restored_applications integer NOT NULL CHECK(expected_restored_applications>0)
);
INSERT INTO game_skill_configuration_manifest VALUES(1,149,128,1,30,35) ON CONFLICT(id) DO NOTHING;
ALTER TABLE game_skill_statuses ADD COLUMN IF NOT EXISTS configuration_version integer NOT NULL DEFAULT 0 CHECK(configuration_version>=0);
CREATE TABLE IF NOT EXISTS game_skill_progression (
 skill_id integer PRIMARY KEY CHECK (skill_id > 0),
 branch text NOT NULL CHECK (branch IN ('left','right','aux')),
 use_native_prerequisites boolean NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS game_skill_prerequisite_overrides (
 skill_id integer NOT NULL REFERENCES game_skill_progression(skill_id),
 ordinal integer NOT NULL CHECK (ordinal > 0),
 prerequisite_id integer NOT NULL REFERENCES game_skill_progression(skill_id),
 PRIMARY KEY(skill_id,ordinal), UNIQUE(skill_id,prerequisite_id),
 CHECK(skill_id<>prerequisite_id)
);
CREATE TABLE IF NOT EXISTS game_skill_growth_policy (
 skill_id integer PRIMARY KEY REFERENCES game_skill_progression(skill_id),
 attribute integer NOT NULL DEFAULT 0 CHECK(attribute IN (0,1,3,5,7,9,61)),
 attribute_cap_rank integer NOT NULL DEFAULT 0 CHECK(attribute_cap_rank >= 0),
 efficiency_cap_rank integer NOT NULL DEFAULT 0 CHECK(efficiency_cap_rank = 0 OR efficiency_cap_rank >= 5),
 range_cap_rank integer NOT NULL DEFAULT 0 CHECK(range_cap_rank = 0 OR range_cap_rank >= 5),
 protection_cap_rank integer NOT NULL DEFAULT 0 CHECK(protection_cap_rank = 0 OR protection_cap_rank >= 5),
 attack_cap_rank integer NOT NULL DEFAULT 0 CHECK(attack_cap_rank = 0 OR attack_cap_rank >= 5),
 attack_targets integer[] NOT NULL DEFAULT '{}' CHECK(array_position(attack_targets,NULL) IS NULL)
);
CREATE TABLE IF NOT EXISTS game_skill_synergies (
 edge_order integer NOT NULL UNIQUE CHECK(edge_order>0),
 target_skill_id integer NOT NULL REFERENCES game_skill_progression(skill_id),
 source_skill_id integer NOT NULL REFERENCES game_skill_progression(skill_id),
 rank_mode text NOT NULL CHECK(rank_mode IN ('hard','effective_raw')),
 effect text NOT NULL,
 per_point_bp integer NOT NULL CHECK(per_point_bp BETWEEN 0 AND 10000),
 PRIMARY KEY(target_skill_id,source_skill_id,effect),
 CHECK(target_skill_id<>source_skill_id)
);
ALTER TABLE game_custom_statuses
 ADD COLUMN IF NOT EXISTS configuration_version integer NOT NULL DEFAULT 0 CHECK(configuration_version>=0),
 ADD COLUMN IF NOT EXISTS replace_native boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS block_move boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS immobile integer NOT NULL DEFAULT 0 CHECK(immobile BETWEEN 0 AND 1),
 ADD COLUMN IF NOT EXISTS attack_speed_is_frequency boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS icon integer NOT NULL DEFAULT 0 CHECK(icon>=0),
 ADD COLUMN IF NOT EXISTS icon_known boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS hidden boolean NOT NULL DEFAULT false;
