$skill_config$::jsonb;
 row jsonb;
 id integer;
 fresh boolean;
 fresh_members integer[] := '{}';
 ord bigint;
 entry jsonb;
BEGIN
 FOR row IN SELECT value FROM jsonb_array_elements(seed->'Skills') LOOP
  id := (row->'Identity'->>'ID')::integer;
  IF NOT EXISTS(SELECT 1 FROM gamedata.ov_skilldesc WHERE skill_id=id AND skill_level=1) THEN
   RAISE EXCEPTION 'skill progression references missing native skill %',id;
  END IF;
  INSERT INTO game_skill_progression(skill_id,branch,use_native_prerequisites)
   VALUES(id,row->'Identity'->>'Branch',(row->>'UseNativePrerequisites')::boolean)
   ON CONFLICT(skill_id) DO NOTHING;
  fresh := FOUND;
  IF fresh THEN fresh_members := array_append(fresh_members,id); END IF;
  -- Only a first-time member installs children. Replaying must not reintroduce
  -- an administrator's intentionally removed prerequisite or overwrite policy.
  IF fresh THEN
   INSERT INTO game_skill_growth_policy VALUES(id,
    (row->'Policy'->>'Attribute')::integer,(row->'Policy'->>'AttributeCapRank')::integer,
    (row->'Policy'->>'EfficiencyCapRank')::integer,(row->'Policy'->>'RangeCapRank')::integer,
    (row->'Policy'->>'ProtectionCapRank')::integer,(row->'Policy'->>'AttackCapRank')::integer,
    ARRAY(SELECT value::integer FROM jsonb_array_elements_text(COALESCE(NULLIF(row->'Policy'->'AttackTargets','null'::jsonb),'[]'::jsonb))));
  END IF;
 END LOOP;
 -- Explicit prerequisite exception: all other members read the native table.
 FOR row IN SELECT value FROM jsonb_array_elements(seed->'Skills') WHERE NOT (value->>'UseNativePrerequisites')::boolean LOOP
  id := (row->'Identity'->>'ID')::integer;
  IF id = ANY(fresh_members) THEN
  FOR entry,ord IN SELECT value,ordinality FROM jsonb_array_elements(row->'Identity'->'Prerequisites') WITH ORDINALITY LOOP
   INSERT INTO game_skill_prerequisite_overrides VALUES(id,ord,entry::integer) ON CONFLICT DO NOTHING;
  END LOOP;
  END IF;
 END LOOP;
 FOR row,ord IN SELECT value,ordinality FROM jsonb_array_elements(seed->'Synergies') WITH ORDINALITY WHERE (value->>'Target')::integer = ANY(fresh_members) LOOP
  INSERT INTO game_skill_synergies VALUES(ord,(row->>'Target')::integer,(row->>'Source')::integer,
   row->>'RankMode',row->>'Effect',(row->>'PerPointBP')::integer) ON CONFLICT DO NOTHING;
 END LOOP;
 FOR row IN SELECT value FROM jsonb_array_elements(seed->'States') LOOP
  INSERT INTO game_custom_statuses(status_id,status_level,name,description,status_type,duration_sec,
   replace_native,block_move,immobile,attack_speed_is_frequency,icon,icon_known,hidden,configuration_version)
  VALUES((row->>'ID')::integer,(row->>'Level')::integer,row->>'Name',row->>'Desc',
   (row->>'Type')::integer,(row->>'DurationSec')::integer,
   (row->>'ID')::integer NOT IN (10009,10111),(row->>'BlockMove')::boolean,
   (row->>'Immobile')::integer,(row->>'AttackSpeedIsFrequency')::boolean,
   (row->>'Icon')::integer,(row->>'IconKnown')::boolean,(row->>'Hidden')::boolean,62)
  ON CONFLICT(status_id,status_level) DO NOTHING;
  fresh := FOUND;
  IF fresh THEN
   FOR entry,ord IN SELECT value,ordinality FROM jsonb_array_elements(COALESCE(NULLIF(row->'Affixes','null'::jsonb),'[]'::jsonb)) WITH ORDINALITY LOOP
    INSERT INTO game_custom_status_affixes VALUES((row->>'ID')::integer,(row->>'Level')::integer,
     ord,(entry->>'Attr')::integer,(entry->>'Value')::integer,(entry->>'Mode')::integer);
   END LOOP;
  END IF;
 END LOOP;
 FOR row IN SELECT value FROM jsonb_array_elements(seed->'Applications') LOOP
  INSERT INTO game_skill_statuses(skill_id,skill_level,status_order,status_id,status_level,chance_bp,duration_sec,configuration_version)
   VALUES((row->>'SkillID')::integer,(row->>'Rank')::integer,1,(row->'App'->>'ID')::integer,
    (row->'App'->>'Level')::integer,(row->'App'->>'ChanceBP')::integer,(row->'App'->>'DurationSec')::integer,62)
   ON CONFLICT(skill_id,skill_level,status_order) DO NOTHING;
 END LOOP;
END
